import math
import itertools

def is_perfect_square(k):
    if k < 0:
        return False
    sqrt_k = int(math.sqrt(k))
    return sqrt_k * sqrt_k == k

def check_permutation(p):
    """Checks if a permutation p satisfies the cool integer condition."""
    prefix_sum = 0
    for x in p:
        prefix_sum += x
        if is_perfect_square(prefix_sum):
            return False
    return True

def is_cool_integer_brute_force(n):
    """Checks if n is a cool integer by testing all n! permutations."""
    if n <= 0:
        return False

    elements = range(1, n + 1)

    # For n > 10, this will be too slow, but the task specified this for n <= 10.
    print(f"--- Checking n = {n}. Permutations: {math.factorial(n)} ---")

    for p in itertools.permutations(elements):
        if check_permutation(p):
            # Found at least one valid permutation
            return True

    # No valid permutation found
    return False

# Test for small values
for n in range(1, 11):
    is_cool = is_cool_integer_brute_force(n)
    print(f"n={n} is cool: {is_cool}")

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(n**0.5)
    return sqrt_n * sqrt_n == n

def S(n):
    return n * (n + 1) // 2

# Check the condition for small n
print("n | S_n | Is S_n a square?")
for n in range(1, 11):
    sn = S(n)
    is_sq = is_perfect_square(sn)
    print(f"{n:2} | {sn:3} | {is_sq}")

